"""A compact HTML minifier helper."""
import re

_DROP_END = set('html head body li dt dd rt rp optgroup option colgroup thead tbody tfoot tr td th'.split())
_BOOL = set('allowfullscreen async autofocus autoplay checked controls default defer disabled formnovalidate hidden inert ismap itemscope loop multiple muted nomodule novalidate open playsinline readonly required reversed selected'.split())
_TOKEN = re.compile(r'<!--[\s\S]*?-->|<![^>]*>|</?[A-Za-z][^>]*>|[^<]+|<')
_ATTR = re.compile(r'''([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+)))?''')

def minify_html(src, opts=None):
    o = opts or {}
    def flag(name):
        return bool(o.get('html_'+name.replace('-', '_'), o.get('html-'+name, False)))
    comments, special = flag('keep-comments'), flag('keep-special-comments')
    docs, ends = flag('keep-document-tags'), flag('keep-end-tags')
    quotes, defaults, preserve_ws = flag('keep-quotes'), flag('keep-default-attrvals'), flag('keep-whitespace')
    out=[]
    for m in _TOKEN.finditer(src):
        t=m.group()
        if t.startswith('<!--'):
            if comments or (special and (t.startswith('<!--[if') or t.startswith('<!--#'))): out.append(t)
            continue
        if t.startswith('<!'):
            if re.match(r'(?is)<!doctype\s+html\s*>',t): out.append('<!doctype html>')
            else: out.append(t)
            continue
        if t.startswith('</'):
            z=re.match(r'</\s*([\w:-]+)',t)
            if z:
                n=z.group(1).lower()
                if docs or n not in ('html','head','body'):
                    if ends or n not in _DROP_END: out.append('</'+n+'>')
            continue
        if t.startswith('<') and len(t)>1 and t[1].isalpha():
            z=re.match(r'<\s*([\w:-]+)',t)
            if not z: out.append(t); continue
            n=z.group(1).lower()
            if not docs and n in ('html','head','body'): continue
            attrs=[]
            for a in _ATTR.finditer(t[z.end():]):
                k=a.group(1).lower()
                v=next((x for x in a.groups()[1:] if x is not None),None)
                if v == '': continue
                if v is not None and not defaults and k in _BOOL and v.lower()==k: v=None
                if v is not None and not defaults and k=='type' and ((n=='script' and v.lower() in ('text/javascript','application/javascript')) or (n=='style' and v.lower()=='text/css')): continue
                if v is not None and not defaults and n=='input' and k=='type' and v.lower()=='text': continue
                if v is None: attrs.append(' '+k)
                elif quotes: attrs.append(' '+k+'="'+v+'"')
                elif re.fullmatch(r'[A-Za-z0-9._:/#?&=+-]+',v): attrs.append(' '+k+'='+v)
                else:
                    q='"' if "'" in v and '"' not in v else "'" if '"' in v and "'" not in v else '"'
                    attrs.append(' '+k+'='+q+v+q)
            out.append('<'+n+''.join(attrs)+('/>' if t.rstrip().endswith('/>') and n not in 'area base br col embed hr img input link meta param source track wbr'.split() else '>'))
            continue
        if t.isspace():
            if out and out[-1].endswith('>') and out[-1].startswith('</'): continue
            if out and not out[-1].endswith('>') and out[-1]: out.append('\n' if '\n' in t else ' ')
            continue
        t=re.sub(r'[\t\r\n\f ]+',lambda x:'\n' if '\n' in x.group() else ' ',t)
        if not preserve_ws and (not out or out[-1].endswith('>')): t=t.strip()
        out.append(t)
    return ''.join(out).strip()
