"""JSON minifier helper with compact numeric formatting."""
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_EVEN

_NUM = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")


def _number(token: str, precision: int) -> str:
    try:
        d = Decimal(token)
    except InvalidOperation:
        return token
    if d.is_zero():
        return "0"
    if precision > 0:
        digits = len(d.normalize().as_tuple().digits)
        quantum = Decimal(1).scaleb(d.adjusted() - precision + 1)
        d = d.quantize(quantum, rounding=ROUND_HALF_EVEN)
        if d.is_zero():
            return "0"
    # Build equivalent plain and exponent spellings, selecting the shorter.
    tup = d.normalize().as_tuple()
    digs = ''.join(map(str, tup.digits))
    exp = tup.exponent
    sign = '-' if tup.sign else ''
    point = len(digs) + exp
    if point <= 0:
        plain = sign + '0.' + '0' * (-point) + digs
    elif point >= len(digs):
        plain = sign + digs + '0' * (point - len(digs))
    else:
        plain = sign + digs[:point] + '.' + digs[point:]
    candidates = [plain]
    for split in range(1, len(digs) + 1):
        mantissa = digs[:split] + ('.' + digs[split:] if split < len(digs) else '')
        exponent = point - split
        candidates.append(sign + mantissa + 'e' + str(exponent))
    return min(candidates, key=len)


def minify_json(text: str, precision: int = 0, keep_numbers: bool = False) -> str:
    """Remove insignificant JSON whitespace and shorten numeric tokens."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '"':
            start = i
            i += 1
            while i < n:
                if text[i] == '\\':
                    i += 2
                elif text[i] == '"':
                    i += 1
                    break
                else:
                    i += 1
            out.append(text[start:i])
        elif c in ' \t\r\n':
            i += 1
        elif c == '-' or c.isdigit():
            m = _NUM.match(text, i)
            if m:
                token = m.group()
                out.append(token if keep_numbers else _number(token, precision))
                i = m.end()
            else:
                out.append(c)
                i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)

