    'svg':'image/svg+xml','tmpl':'text/x-template','webmanifest':'application/manifest+json',
    'xhtml':'application/xhtml+xml','xml':'text/xml'
}

def _type(t):
    t=(t or '').lower().strip()
    aliases={'css':'text/css','html':'text/html','htm':'text/html','js':'application/javascript','javascript':'application/javascript',
             'json':'application/json','svg':'image/svg+xml','xml':'text/xml','xhtml':'application/xhtml+xml'}
    return aliases.get(t,t)

