"""JSON minifier helper with compact numeric formatting."""
import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_NUM = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?")


def _number(token: str, precision: int) -> str:
    try:
        d = Decimal(token)
    except InvalidOperation:
        return token
    if d.is_zero():
        return "0"
    if precision > 0:
        original = d
        digits = len(d.normalize().as_tuple().digits)
        quantum = Decimal(1).scaleb(d.adjusted() - precision + 1)
        d = d.quantize(quantum, rounding=ROUND_HALF_UP)
        if d.is_zero():
            return "0"
        if d == original and re.fullmatch(r'-?0\.\d+', token):
            return token.rstrip('0').rstrip('.')
    # Build equivalent plain and exponent spellings, selecting the shorter.
    tup = d.normalize().as_tuple()
    digs = ''.join(map(str, tup.digits))
    exp = tup.exponent
    sign = '-' if tup.sign else ''
    point = len(digs) + exp
    candidates = []
    for split in range(1, len(digs) + 1):
        mantissa = digs[:split] + ('.' + digs[split:] if split < len(digs) else '')
        exponent = point - split
        candidates.append(sign + mantissa + 'e' + str(exponent))
    # Avoid materializing huge runs of zeroes when an exponent is clearly
    # shorter (valid JSON numbers can have arbitrarily large exponents).
    plain_len = (len(sign) + (2 - point + len(digs) if point <= 0 else
                              point + (1 + len(digs) - point if point < len(digs) else 0)
                              if point < len(digs) else len(digs) + point - len(digs)))
    if plain_len <= min(map(len, candidates)):
        if point <= 0:
            plain = sign + '0.' + '0' * (-point) + digs
        elif point >= len(digs):
            plain = sign + digs + '0' * (point - len(digs))
        else:
            plain = sign + digs[:point] + '.' + digs[point:]
        candidates.append(plain)
    return min(candidates, key=lambda x: (len(x), 'e' in x, '.' in x))


def minify_json(text: str, precision: int = 0, keep_numbers: bool = False) -> str:
    """Remove insignificant JSON whitespace and shorten numeric tokens."""
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c == '"':
            start = i
            i += 1
            closed = False
            while i < n:
                if text[i] == '\\':
                    i += 2
                elif text[i] == '"':
                    i += 1
                    closed = True
                    break
                else:
                    i += 1
            if not closed:
                return ''
            out.append(text[start:i])
        elif c in ' \t\r\n':
            i += 1
        elif c == ',':
            j = i + 1
            while j < n and text[j] in ' \t\r\n':
                j += 1
            if j < n and text[j] in '}]':
                i += 1
            else:
                out.append(c)
                i += 1
        elif c == '-' or c.isdigit():
            m = _NUM.match(text, i)
            if m:
                token = m.group()
                out.append(token if keep_numbers else _number(token, precision))
                i = m.end()
            else:
                out.append(c)
                i += 1
        else:
            out.append(c)
            i += 1
    return ''.join(out)

